<?php require __DIR__.'/../bootstrap.php';require_admin();$id=(int)getv('id');$entry=(string)getv('entry','');$s=db()->prepare('SELECT * FROM media_assets WHERE id=? AND kind=\'archive\'');$s->execute([$id]);$m=$s->fetch();if(!$m||!$m['storage_path'])exit('Archive not found.');$path=__DIR__.'/..'.$m['storage_path'];if(!class_exists('ZipArchive'))exit('ZipArchive is unavailable.');$zip=new ZipArchive();if($zip->open($path)!==true)exit('Could not open archive.');$idx=$zip->locateName($entry,ZipArchive::FL_NOCASE);if($idx===false)exit('Entry not found.');$st=$zip->statIndex($idx);$stream=$zip->getStream($entry);if(!$stream)exit('Could not read entry.');$mime='application/octet-stream';$n=strtolower($entry);foreach(['.jpg'=>'image/jpeg','.jpeg'=>'image/jpeg','.png'=>'image/png','.gif'=>'image/gif','.webp'=>'image/webp','.mp3'=>'audio/mpeg','.wav'=>'audio/wav','.ogg'=>'audio/ogg','.mp4'=>'video/mp4','.webm'=>'video/webm','.mov'=>'video/quicktime','.txt'=>'text/plain','.json'=>'application/json','.pdf'=>'application/pdf'] as $ext=>$mt)if(str_ends_with($n,$ext)){$mime=$mt;break;}header('Content-Type: '.$mime);header('Content-Length: '.(int)($st['size']??0));header('Content-Disposition: inline; filename="'.basename($entry).'"');fpassthru($stream);fclose($stream);$zip->close();exit;